const assert = require('node:assert/strict');
const M = require('./model.js');
const chapters = M.clone(M.INITIAL);
assert.deepEqual(M.intervals(chapters).map(x => x.duration), [200, 295, 355, 270]);
for (const time of ['3:20', '00:60', '18:40', '19:00', '-1:00', 'xx:yy']) assert.ok(M.parseTime(time).error, time);
assert.equal(M.parseTime('18:39').value, 1119);
assert.ok(M.validateDraft(chapters, { id: 'first-try', time: '08:15', title: 'Título preservado' }).errors.time);
assert.ok(M.validateDraft(chapters, { id: 'opening', time: '00:01', title: 'Abertura' }).errors.time);
assert.ok(M.validateDraft(chapters, { id: 'first-try', time: '03:20', title: ' ' }).errors.title);
assert.throws(() => M.removeChapter(chapters, 'opening'));
const added = M.saveDraft(chapters, { id: null, time: '05:00', title: 'Uma nova pergunta' }, 'new');
assert.deepEqual(added.chapters.map(x => x.time), [0, 200, 300, 495, 850]);
const moved = M.saveDraft(added.chapters, { id: 'new', time: '16:00', title: 'Pergunta final' });
assert.equal(moved.chapters.at(-1).title, 'Pergunta final');
assert.equal(M.intervals(moved.chapters).at(-1).duration, 160);
assert.equal(M.removeChapter(moved.chapters, 'new').length, 4);
assert.equal(M.exportText(chapters), '00:00 Abertura\n03:20 A primeira tentativa\n08:15 Quando o plano muda\n14:10 O que ficou\n');
assert.equal(M.validChapters(chapters), true);
assert.equal(M.validChapters([{ id: 'x', time: 1, title: 'Não começa no zero' }]), false);
assert.equal(M.validChapters([...chapters, { id: 'duplicate', time: 850, title: 'Duplicado' }]), false);
assert.equal(chapters[1].time, 200);
console.log('Regras do modelo: todas as asserções passaram.');
